from synth_line_normalizer import run


def test_run_strips_and_drops_empty_lines() -> None:
    assert run(["  first ", "  ", "second"]) == ["first", "second"]


def test_run_can_preserve_empty_lines() -> None:
    assert run([" first ", "  "], drop_empty=False) == ["first", ""]
